using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S0.Certificates;

internal sealed class SkeletonChannelRetractionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S0/Certificates/SkeletonChannelRetraction.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Fixed terminal observations admit an explicit output retraction without increasing the original canonical state budget.",
        H("Sample-Preserving Channel Retraction"),
        Blocks(
            Describe.Lean(DescribeId.Create("channel-retraction-map-channels"), DeclarationHandle.Create(Prefix + "mapChannels"), H("mapChannels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Postcompose the two terminal channels; retain the complete transition data."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-channel-map"), DeclarationHandle.Create(Prefix + "channelMap"), H("channelMap"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Select the postcomposition associated with the original terminal channel."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-eval-from-map-channels"), DeclarationHandle.Create(Prefix + "evalFrom_mapChannels"), H("evalFrom_mapChannels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Exact evaluation commutes with channelwise postcomposition, including none."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-eval-map-channels"), DeclarationHandle.Create(Prefix + "eval_mapChannels"), H("eval_mapChannels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Start-state version for the existing block-code input representation."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-signature-map"), DeclarationHandle.Create(Prefix + "signatureMap"), H("signatureMap"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every old used signature maps to a used signature with the same return."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-signature-map-surjective"), DeclarationHandle.Create(Prefix + "signatureMap_surjective"), H("signatureMap_surjective"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Output retraction creates no signature outside the image of old ones."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-canonical-state-card-map-channels-le"), DeclarationHandle.Create(Prefix + "canonical_state_card_mapChannels_le"), H("canonical_state_card_mapChannels_le"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Canonical state cost cannot increase under either terminal retraction."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-fixed-observation-preserved"), DeclarationHandle.Create(Prefix + "fixed_observation_preserved"), H("fixed_observation_preserved"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Fixed observed labels survive even when unobserved outputs change."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-recurrent-retract"), DeclarationHandle.Create(Prefix + "recurrentRetract"), H("recurrentRetract"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("In radix four, recurrent output two may be retracted to zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-transient-retract"), DeclarationHandle.Create(Prefix + "transientRetract"), H("transientRetract"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("In radix four, transient output zero may be retracted to one."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-recurrent-retract-ne-two"), DeclarationHandle.Create(Prefix + "recurrentRetract_ne_two"), H("recurrentRetract_ne_two"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The recurrent retraction has precisely the intended forbidden-value exclusion."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-transient-retract-ne-zero"), DeclarationHandle.Create(Prefix + "transientRetract_ne_zero"), H("transientRetract_ne_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The transient retraction excludes zero without altering any other label."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-normal-range"), DeclarationHandle.Create(Prefix + "NormalRange"), H("NormalRange"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Finite-state candidates with the reduced terminal alphabets."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("channel-retraction-retracted-normal-range"), DeclarationHandle.Create(Prefix + "retracted_normalRange"), H("retracted_normalRange"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The explicit retraction constructs that range for every partial skeleton."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("channel-retraction-normalized-sample-feasibility-iff"), DeclarationHandle.Create(Prefix + "normalized_sample_feasibility_iff"), H("normalized_sample_feasibility_iff"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Reduced-output search is equisatisfiable at the same canonical budget. Only the given observations are assumed to avoid the two forbidden labels; the unknown original machine's unobserved outputs are unrestricted."))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Automata/BinaryZeckendorfBlockSkeleton"))]));
